class Solution {
public:
    int diagonalSum(vector<vector<int>>& mat) {
        int ans=0;
        int n=mat.size();
        for(int i=0;i<n;i++)
            ans+=mat[i][i]+mat[i][n-i-1];
        if(n&1)
            ans-=mat[n/2][n/2];
        return ans;
    }
};

class Solution(object):
    def diagonalSum(self, mat):
        """
        :type mat: List[List[int]]
        :rtype: int
        """
        n = len(mat)
        ans = 0
        for i in range(n):
            ans += mat[i][i]
        for i in range(n):
            ans += mat[i][n - 1 - i]
        if n % 2 == 1:
            ans -= mat[n // 2][n // 2]
